<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {WarningFilled} from '@element-plus/icons-vue'
import type {DataOperationCommand} from './data-operation-draft'
import {errorMessage,onIdentityChange} from '@/core/http'
import {dataStreamTemplate,type DataStreamItem} from '../device-types/data-stream-publication-api'
import ModbusRtuParserDialog from './ModbusRtuParserDialog.vue'
import GatewayDataParserDialog from './GatewayDataParserDialog.vue'
import DataDownlinkFunctionDialog from './DataDownlinkFunctionDialog.vue'
import DataPropertyFunctionDialog from './DataPropertyFunctionDialog.vue'
import type {DataPropertyFunction} from './data-property-preview-api'
import {type DataDownlinkFunction} from './data-downlink-function-api'
import type {GatewayDataParser} from './gateway-data-parser-api'
import type {ModbusRtuParser} from './modbus-rtu-parser-api'
import type {SubdeviceModbusRtuParser} from './subdevice-modbus-rtu-parser-api'
import {dataOperationLabels,dataOperationAllowed,newDataOperationId,normalizeDataOperations,type DataOperation,type DataOperationKind,type DataOperations,type DataOperationContext} from './data-operations-api'
const props=defineProps<{modelValue:DataOperations;projectId:string;typeId:string;scopeKey:string;stream?:DataStreamItem;streams:readonly DataStreamItem[];deviceKind:string;payloadProtocol:string;sourceContexts?:readonly DataOperationContext[];disabled?:boolean;readOnly?:boolean;autoAdd?:boolean;detail?:boolean;command?:DataOperationCommand;legacy?:boolean;requestError?:string;recoveryPending?:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:DataOperations];locked:[value:boolean];'cancel-add':[];command:[value:{kind:'ADD'|'SORT'}|{kind:'EDIT'|'REMOVE';id:string}];commit:[value:DataOperations];cancelCommand:[]}>()
const descriptions:Record<DataOperationKind,string>={MODBUS_RTU:'通过可视化配置解析规则，实现对 Modbus RTU 数据上报进行解析，生成设备属性。',PROPERTY:'编写 Javascript 云函数，解析自定义上报数据，生成设备的属性集合，实现属性上报。',GATEWAY_PROPERTY:'编写 Javascript 云函数，解析自定义上报数据，生成网关上报协议，实现云网关。',DATA_DOWNLINK:'通过云函数生成自定义数据，通过指定的自定义数据流下发到当前上报数据的设备。'}
const sorting=ref(false),removing=ref<DataOperation>(),dragged=ref('')
const picker=ref(props.autoAdd===true),editing=ref<{id:string;kind:DataOperationKind;before?:DataOperation}>(),modalBusy=ref(false),error=ref('')
const context=computed(()=>({deviceKind:props.deviceKind,payloadProtocol:props.payloadProtocol,streamFormat:props.stream?.format??'',streamTemplate:props.stream?dataStreamTemplate(props.stream):undefined})),kinds:readonly DataOperationKind[]=['MODBUS_RTU','PROPERTY','GATEWAY_PROPERTY','DATA_DOWNLINK']
const locked=computed(()=>picker.value||!!editing.value||modalBusy.value||!!removing.value||sorting.value),counts=computed(()=>Object.fromEntries(kinds.map(kind=>[kind,props.modelValue.operations.filter(row=>row.kind===kind).length])))
const nativeModel=computed(()=>editing.value?.before?.subdeviceNativeParser??editing.value?.before?.nativeParser)
const contexts=computed(()=>props.sourceContexts??[context.value])
const allowedKind=(kind:DataOperationKind)=>contexts.value.every(value=>dataOperationAllowed(kind,value))
function canAdd(kind:DataOperationKind){return allowedKind(kind)&&props.modelValue.operations.length<13&&(counts.value[kind]??0)<(kind==='MODBUS_RTU'?10:1)}
function openAdd(){if(props.disabled||props.readOnly||locked.value)return;error.value='';picker.value=true}
function cancelPicker(){if(props.disabled||modalBusy.value)return;picker.value=false;emit('cancel-add');if(props.detail)emit('cancelCommand')}
function begin(kind:DataOperationKind,before?:DataOperation){
 if(props.disabled||props.readOnly||modalBusy.value||before&&!props.modelValue.operations.includes(before)||!before&&!canAdd(kind))return
 editing.value={id:before?.id??newDataOperationId(),kind,...(before?{before}:{})};picker.value=false;error.value=''
}
function cancel(){if(props.disabled||props.recoveryPending||modalBusy.value)return;reset();if(props.detail)emit('cancelCommand');else if(props.autoAdd)emit('cancel-add')}
function commit(row:DataOperation){
 if(props.disabled||props.readOnly||modalBusy.value||!editing.value||row.id!==editing.value.id||row.kind!==editing.value.kind)return
 try{const operations=props.modelValue.operations.some(value=>value.id===row.id)?props.modelValue.operations.map(value=>value.id===row.id?row:value):[...props.modelValue.operations,row],value=props.legacy?Object.freeze({profile:'DATA_OPERATIONS_V1',operations:Object.freeze(operations)}) as DataOperations:normalizeDataOperations({profile:'DATA_OPERATIONS_V1',operations});error.value='';if(props.detail)emit('commit',value);else{editing.value=undefined;emit('update:modelValue',value)}}catch(cause){error.value=errorMessage(cause)}
}
function saveNative(value:ModbusRtuParser|SubdeviceModbusRtuParser){const current=editing.value;if(current?.kind==='MODBUS_RTU')commit({id:current.id,kind:current.kind,...(value.useSubdeviceAddress?{subdeviceNativeParser:value as SubdeviceModbusRtuParser}:{nativeParser:value as ModbusRtuParser})})}
function saveGateway(value:GatewayDataParser){const current=editing.value;if(current?.kind==='GATEWAY_PROPERTY')commit({id:current.id,kind:current.kind,gatewayParser:value})}
function saveDownlink(value:DataDownlinkFunction){const current=editing.value;if(current?.kind==='DATA_DOWNLINK')commit({id:current.id,kind:current.kind,dataDownlink:value,transportTarget:'ORIGINAL_PHYSICAL_DEVICE'})}
function saveProperty(value:DataPropertyFunction){const current=editing.value;if(current?.kind==='PROPERTY')commit({id:current.id,kind:current.kind,function:value,...(current.before?.inputContract?{inputContract:current.before.inputContract}:{})})}
function remove(row:DataOperation){if(props.disabled||props.readOnly||locked.value||!props.modelValue.operations.includes(row))return;error.value='';emit('update:modelValue',Object.freeze({profile:'DATA_OPERATIONS_V1',operations:Object.freeze(props.modelValue.operations.filter(item=>item.id!==row.id))}) as DataOperations)}
function reset(){picker.value=false;editing.value=undefined;modalBusy.value=false;removing.value=undefined;sorting.value=false;dragged.value='';error.value=''}
function request(kind:'ADD'|'SORT'|'EDIT'|'REMOVE',row?:DataOperation){if(props.disabled||props.readOnly||locked.value)return;if(props.detail)emit('command',kind==='EDIT'||kind==='REMOVE'?{kind,id:row!.id}:{kind});else if(kind==='ADD')openAdd();else if(kind==='EDIT'&&row)begin(row.kind,row);else if(kind==='REMOVE'&&row)remove(row)}
function reorder(from:string,to:string){if(props.disabled||!sorting.value||props.recoveryPending)return;const list=[...props.modelValue.operations],a=list.findIndex(row=>row.id===from),b=list.findIndex(row=>row.id===to);if(a<0||b<0||a===b)return;const [row]=list.splice(a,1);list.splice(b,0,row!);emit('update:modelValue',normalizeDataOperations({profile:'DATA_OPERATIONS_V1',operations:list}))}
function move(index:number,by:number){const to=index+by;if(to<0||to>=props.modelValue.operations.length)return;reorder(props.modelValue.operations[index]!.id,props.modelValue.operations[to]!.id)}
function startDrag(event:DragEvent,id:string){if(props.disabled||!sorting.value){event.preventDefault();return}dragged.value=id;event.dataTransfer?.setData('text/plain',id)}
function drop(id:string){const from=dragged.value;dragged.value='';reorder(from,id)}
function saveSort(){if(!props.disabled&&!props.recoveryPending&&sorting.value)emit('commit',props.modelValue)}
function confirmRemoval(){if(props.disabled||!removing.value)return;if(props.modelValue.operations.length<=1){error.value='请至少保留1项操作，当前操作尚未移除。';return}emit('commit',normalizeDataOperations({profile:'DATA_OPERATIONS_V1',operations:props.modelValue.operations.filter(row=>row.id!==removing.value!.id)}))}
watch(()=>props.command,value=>{if(!props.detail)return;if(!value){reset();return}if(props.disabled||props.readOnly)return;if(value.kind==='ADD')picker.value=true;else if(value.kind==='SORT')sorting.value=true;else if('id' in value){const row=props.modelValue.operations.find(row=>row.id===value.id);if(row){if(value.kind==='EDIT')begin(row.kind,row);else removing.value=row}}},{flush:'post'})
watch(()=>props.recoveryPending,value=>{if(value)reset()})
watch(locked,value=>emit('locked',value),{immediate:true,flush:'sync'})
watch([()=>props.scopeKey,()=>props.projectId,()=>props.typeId,()=>props.stream?.identifier,()=>props.deviceKind,()=>props.payloadProtocol],reset)
const dispose=onIdentityChange(reset);onScopeDispose(()=>{reset();dispose();emit('locked',false)})
</script>
<template><section class="data-operations-editor">
 <template v-if="detail"><header class="detail-data-header"><h3>操作</h3><div><el-button v-if="sorting" link type="primary" :disabled="disabled" @click="cancel">取消</el-button><el-button v-if="sorting" link type="primary" :disabled="disabled" @click="saveSort">保存排序</el-button><el-button v-else link type="primary" :disabled="disabled||locked" @click="request('SORT')">排序</el-button><el-button v-if="!sorting" link type="primary" :disabled="disabled||locked||modelValue.operations.length>=13" @click="request('ADD')">添加操作</el-button></div></header>
 <div class="detail-data-list"><div v-for="(row,index) in modelValue.operations" :key="row.id" class="detail-data-row" :data-operation-id="row.id" :draggable="sorting&&!disabled" @dragstart="startDrag($event,row.id)" @dragover.prevent @drop.prevent="drop(row.id)"><span class="detail-data-icon"><ReferenceIcon :glyph="row.kind==='MODBUS_RTU'?'󰌗':row.kind==='DATA_DOWNLINK'?'󰿨':'󰡱'"/></span><span>{{dataOperationLabels[row.kind]}}</span><div><el-button v-if="sorting" size="small" :disabled="disabled" :aria-label="'拖动排序操作 '+(index+1)" @keydown.up.prevent="move(index,-1)" @keydown.down.prevent="move(index,1)"><ReferenceIcon glyph="󰍜"/></el-button><el-button size="small" :disabled="disabled||locked" :aria-label="'编辑操作 '+(index+1)" @click="request('EDIT',row)"><ReferenceIcon glyph="󰏫"/></el-button><el-button size="small" type="danger" :disabled="disabled||locked" :aria-label="'移除操作 '+(index+1)" @click="request('REMOVE',row)"><ReferenceIcon glyph="󰆴"/></el-button></div></div></div></template>
 <template v-else>
 <el-table :data="[...modelValue.operations]" :show-header="false" empty-text="暂无数据" class="data-operation-table"><el-table-column><template #default="{row}">{{dataOperationLabels[row.kind as DataOperationKind]}}</template></el-table-column><el-table-column v-if="!readOnly" width="50"><template #default="{row,$index}"><el-button circle size="small" :aria-label="'编辑操作 '+($index+1)" :disabled="disabled||locked" @click="begin(row.kind,row)"><ReferenceIcon glyph="󰏫"/></el-button></template></el-table-column><el-table-column v-if="!readOnly" width="50"><template #default="{row,$index}"><el-button circle size="small" type="danger" :aria-label="'删除操作 '+($index+1)" :disabled="disabled||locked" @click="remove(row)"><ReferenceIcon glyph="󰆴"/></el-button></template></el-table-column></el-table>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="!readOnly" :disabled="disabled||locked||modelValue.operations.length>=13" @click="openAdd">添加操作</el-button>
 </template>
 <el-dialog v-if="picker" :model-value="true" title="添加操作" :width="detail?'min(800px,94vw)':'min(620px,94vw)'" :top="detail?'10vh':undefined" :lock-scroll="!detail" :close-on-press-escape="!disabled" :show-close="!disabled" :close-on-click-modal="false" :before-close="cancelPicker" append-to-body><div class="data-operation-options"><el-button v-for="kind in kinds.filter(allowedKind)" :key="kind" class="data-operation-option" :aria-label="dataOperationLabels[kind]" :disabled="disabled||!canAdd(kind)" @click="begin(kind)"><span>{{dataOperationLabels[kind]}}<small>{{descriptions[kind]}}</small></span></el-button></div><template #footer><el-button :disabled="disabled" @click="cancelPicker">取消</el-button></template></el-dialog>
 <ModbusRtuParserDialog v-if="editing?.kind==='MODBUS_RTU'&&stream" :project-id="projectId" :type-id="typeId" :scope-key="scopeKey" :stream-identifier="stream.identifier" :model-value="nativeModel" :subdevice-address-allowed="deviceKind==='SUB_DEVICE'" :allow-fixed-subdevice-address="!legacy" :disabled="disabled" :validation-error="error||requestError" :top="detail?'10vh':undefined" @busy="modalBusy=$event" @save="saveNative" @cancel="cancel"/>
 <GatewayDataParserDialog v-if="editing?.kind==='GATEWAY_PROPERTY'&&stream" :project-id="projectId" :type-id="typeId" :scope-key="scopeKey" :stream="stream" :model-value="editing.before?.gatewayParser" :disabled="disabled" :validation-error="error||requestError" :top="detail?'10vh':undefined" @busy="modalBusy=$event" @save="saveGateway" @cancel="cancel"/>
 <DataDownlinkFunctionDialog v-if="editing?.kind==='DATA_DOWNLINK'&&stream" :project-id="projectId" :type-id="typeId" :scope-key="scopeKey" :stream-identifier="stream.identifier" :streams="streams" :subdevice="deviceKind==='SUB_DEVICE'" :model-value="editing.before?.dataDownlink" :disabled="disabled" :validation-error="error||requestError" :top="detail?'10vh':undefined" @busy="modalBusy=$event" @save="saveDownlink" @cancel="cancel"/>
 <DataPropertyFunctionDialog v-if="editing?.kind==='PROPERTY'&&stream" :project-id="projectId" :type-id="typeId" :scope-key="scopeKey" :stream="stream" :input-profile="legacy?'LEGACY_SINGLE':'DATA_OPERATIONS_V1'" :input-contract="editing.before?.inputContract" :subdevice="deviceKind==='SUB_DEVICE'" :model-value="editing.before?.function" :disabled="disabled" :validation-error="error||requestError" :top="detail?'10vh':undefined" @busy="modalBusy=$event" @save="saveProperty" @cancel="cancel"/>
 <el-dialog v-if="removing" :model-value="true" title="提示" width="500px" top="10vh" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" :before-close="cancel" append-to-body><div class="operation-removal-prompt"><el-icon aria-hidden="true"><WarningFilled/></el-icon><span>确认移除该操作吗？</span></div><el-alert v-if="error||requestError" :title="error||requestError" type="warning" :closable="false"/><template #footer><el-form :disabled="false"><el-button :disabled="disabled" @click="cancel">取消</el-button><el-button type="primary" :disabled="disabled" @click="confirmRemoval">确定</el-button></el-form></template></el-dialog>
</section></template>
<style scoped>.operation-removal-prompt{display:flex;align-items:center;gap:12px;line-height:24px}.operation-removal-prompt .el-icon{flex:none;font-size:24px;color:var(--el-color-warning)}.detail-data-header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #ebeef5}.detail-data-header h3{margin:0;font-size:14px;font-weight:500}.detail-data-header>div{display:flex;gap:14px}.detail-data-header .el-button+.el-button{margin-left:0}.detail-data-row{display:flex;align-items:center;gap:20px;min-height:86px;padding:20px 28px;border-bottom:1px solid #ebeef5;font-size:14px;color:#606266}.detail-data-row[draggable=true]{cursor:grab}.detail-data-row small{font-size:12px;color:#909399;margin-left:7px}.detail-data-row>div{margin-left:auto;display:flex;gap:7px}.detail-data-row .el-button+.el-button{margin-left:0}.detail-data-icon{display:inline-flex;align-items:center;justify-content:center;flex:none;width:30px;height:30px;border-radius:3px;background:#16834d;color:#fff;font-size:17px}.data-operation-table{width:100%;font-size:14px;color:#606266;margin-bottom:20px}.data-operation-table :deep(.el-table__cell){padding:12px 0}.data-operation-table :deep(.cell){padding:0 10px}.data-operation-table :deep(.el-button.is-circle){width:28px;height:28px;padding:7px}.data-operation-card{border:1px solid var(--el-border-color-lighter);padding:16px;margin:16px 0}.data-operation-card header{display:flex;align-items:center;justify-content:space-between;gap:12px}.data-operation-card h3{font-size:16px;font-weight:500;margin:0}.data-operations-editor p{font-size:13px;color:var(--el-text-color-secondary);line-height:1.7}pre{max-height:300px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;padding:12px;background:var(--el-fill-color-light)}.data-operation-options{display:grid;gap:12px}.data-operation-option{height:auto;min-height:64px;margin:0!important;justify-content:flex-start;text-align:left;padding:14px}.data-operation-option small{display:block;line-height:1.7;color:var(--el-text-color-secondary)}@media(max-width:560px){.data-operation-card header{align-items:flex-start;flex-direction:column}}</style>
